#!/usr/bin/env python3
# reserve_L10b.py — 새 과 L10b(레일의 세 칸 객차) · L10c(조차장의 오타 열차) · 세계 s10(b · c) + 17장 덧붙임 10장(L48d · L43a)
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']; G = d['_글자모양사전']
B = '[2026-11-13 새 과 L10b]'; C = '[2026-11-13 새 과 L10c]'
new = {
 # ── L10b
 '창 셋 달린 회청 객차(창의 빛깔 넷 — 초록 A · 파랑 U · 빨강 G · 노랑 C)': f'코돈(염기 셋이 아미노산 하나를 지정) · 염기 넷 전용 {B} — 세계 s10(레일 = mRNA) 위의 객차 한 대 = 코돈 · 창 셋 = 염기 셋. L10b s1 레일의 객차 일곱(AUG · GAG · CAA · ACC · UAA · UAG · UGA) · L10c 조차장의 열차 여섯. 창의 빛깔은 PIL 이 칠한다(바탕은 맨 유리) — 초록 = A · 빨강 = G 는 L38a 사다리 칸(초록 A-T · 빨강 G-C)에서 왔다. ⚠ 초록 · 노랑 · 빨강을 한 줄로 세우지 않으려고 U 를 파랑으로 했다(신호등 = 방실결절). ⚠ 【회 굳은 격자창 / 손수레에 실려 와 끼워지는 창틀】(통로)과 가른다 — 이쪽은 객차의 빛깔 유리.',
 '네 빛깔 페인트 통 + 예순네 칸 체스판(금빛 구슬 61 + 작은 나무판 3)': f'코돈의 가짓수 4 × 4 × 4 = 64(61 은 아미노산 · 3 은 종결) 전용 {B} — L10b s2 도색장. 창 하나에 페인트 넷 중 하나 · 창이 셋. 체스판의 칸 수가 곧 숫자다(【스물다섯 칸 바둑판 깔개】와 같은 수법) — 구슬 61 과 나무판 3 은 PIL(`L10b_pil1.py` · 세어서 그림).',
 '객차 지붕에서 팔을 뻗어 오른쪽을 가리키는 월계관 황제(흰 토가 · 붉은 띠)': f'개시 코돈 AUG 전용 {B} — L10b s3 맨 앞 객차(창 = 초록 · 파랑 · 빨강). 아우구스투스(Augustus)의 첫 석 자 = A · U · G · 출발을 명하는 팔 = 개시. ⚠ 왕관(코로나) · 로마 투구 + 칼(ROMK)을 쓰지 않는다 — 월계관 · 맨손.',
 '객차 지붕의 나무판 든 셋 — 발레리나 · 비명 지르는 사람 · 원시인': f'종결 코돈 UAA · UAG · UGA 전용 {B} — L10b s4 차막이 앞 세 객차(첫 창이 모두 파랑 = U). 로마자를 그대로 읽는다: 우아아(우아한 발레리나) · 우악(비명) · 우가(원시인). 나무판 = 종결(L10a 의 방출 인자). ⚠ 원시인에게 곤봉을 쥐여 주지 않는다(글루카곤).',
 '다리를 곧게 뻗고 앉은 흰 수염 팔순 할아버지 + 손에 든 종이의 세 잎 클로버': f'tRNA 의 모양(실제 3차원 = L 자 · 평면에 펼친 2차원 = 클로버) · 길이 약 80 뉴클레오타이드 전용 {B} — L10b s5 보라 정거장 안. 이 세계에서 좌석의 사람 = tRNA(L10a). 앉은 몸 = L · 납작한 종이 = 2차원 · 팔을 든 팔순(八旬) = 80. ⚠ 지팡이를 주지 않는다(DnaG). Gemini 는 뒤로 기대앉게 그려 구역 편집 Z1 로 곧추 앉혔다.',
 '번쩍 든 손에서 늘어진 쇠갈고리 둘 + 접이 사다리 + 구슬': f'tRNA 3′ 말단의 CCA 서열에 아미노산이 붙는다 전용 {B} — L10b s6. 글자 모양 그대로: C 자 갈고리 · C 자 갈고리 · A 자 사다리 = C · C · A(【_글자모양사전】) · 끝의 구슬 = 아미노산 · 셋이 달린 끝 = 3′. PIL(`L10b_pil1.py`).',
 '말풍선 속 빛깔 네모 셋 → 구슬 하나': f'tRNA = 번역자(코돈의 말 → 아미노산의 말) 전용 {B} — L10b s7 할아버지 입가. 네모 셋의 빛깔은 발밑 객차의 창(노랑 · 초록 · 초록 = CAA)과 같고 구슬은 손끝의 것과 같은 분홍. PIL.',
 '다 꿴 구슬 사슬을 어깨에 메고 콩 모양 손님채로 걷는 짐꾼(앞 끝 파란 구슬)': f'미토콘드리아 · 엽록체로 갈 단백질은 세포질에서 번역이 끝난 뒤 옮겨진다 전용 {B} — L10b s8. 다 꿰어진 사슬 = 끝난 뒤 · 곁의 작은 카키 천막(지붕의 보라 짝이 꿰면서 지붕 구멍으로 넣는다 = 소포체행은 번역 도중)과 맞쌍.',
 '갈림길 이정표의 화살판 셋 — 빨강 · 파랑 · 초록 구슬': f'신호 펩타이드는 행선지마다 다르다(여러 소기관으로 정확히) 전용 {B} — L10b s9. 빨강 = 소포체(【지붕 위 안내인이 쥔 구슬 사슬 · 사슬 앞 끝의 빨간 구슬】) · 파랑 = 미토콘드리아(콩 모양 손님채) · 초록 = 엽록체(오두막 지붕의 초록 꼬투리). 사슬 앞 끝 구슬의 빛깔 = 주소. 구슬 셋은 PIL.',
 # ── L10c
 '조차장의 열차 여섯 — 원본 열차 + 빨간 펜 동그라미가 하나씩인 오타 열차 다섯': f'점 돌연변이 다섯 가지(침묵 · 과오 · 정지 · 삽입 · 결실 — 위에서 아래로) 전용 {C} — L10c s1 · s3 ~ s9. 열차 = mRNA 의 코돈 줄(AUG GAG CAA ACC AUU UAA) · 위의 구슬 줄 = 그 사슬(금 · 주황 · 분홍 · 청록 · 보라 + 나무판 = 종결). 실제 유전암호 그대로다(`L10c_seq.py` 가 검산): 침묵 ACC → ACU · 과오 GAG → GUG(겸상적혈구의 그 치환) · 정지 CAA → UAA · 삽입 = AUG 뒤에 C · 결실 = GAG 의 첫 G. 열차 · 구슬 · 동그라미 · 선로는 모두 PIL(`L10c_trains.py`).',
 '사람 키만 한 빨간 매직펜을 세워 든 초록 조끼 · 둥근 안경의 교정원': f'오타 표시(점 돌연변이 = 염기쌍 하나의 변화) 전용 {C} — L10c s1. 빨간 펜 동그라미 = 고친 자리. ⚠ 연필로 그리지 않는다(【벽에 걸린 샤프펜슬】 = 샤가프) · 처음 바탕의 「남색 정장 대머리 + 큰 빨간 연필」은 세크레틴 요원과 닮아 구역 편집 ZA2 로 바꿨다.',
 '두 손바닥을 펴 어깨를 으쓱하는 줄무늬 옷의 무언극 배우': f'침묵 돌연변이(코돈은 바뀌어도 아미노산은 그대로 — 유전암호의 중복성) 전용 {C} — L10c s4. 말이 없다 = 침묵. ⚠ 손가락을 입술에 대지 않는다(【쉿 요원】 = 세크레틴).',
 '바나나처럼 길쭉하게 휜 빨간 몸(찡그린 얼굴 · 가는 팔다리) + 손의 검은 구슬': f'겸상적혈구(낫 모양 적혈구) — 과오 돌연변이의 예(글루탐산 → 발린) 전용 {C} — L10c s6. 【가운데가 옅은 분홍으로 옴폭한 붉은 원반】(적혈구)이 휘어 찌그러진 것 · 손의 검은 구슬 = 과오 열차의 검은 구슬(잘못 끼운 아미노산). ⚠ 자루 달린 낫(레닌) · 하늘의 초승달(CAM)로 그리지 않는다 — 계획의 다른 그림(P4 멘델 · P7)에서도 겸상적혈구는 이 물건으로.',
 '삽날에 노란 유리판을 얹어 든 노란 멜빵바지 일꾼 / 빨간 유리판을 끼고 달아나는 갈색 원숭이': f'삽입 / 결실(→ 틀이동 돌연변이) 전용 {C} — L10c s8 · s9. 삽으로 떠 넣는다 = 삽입 · 원숭이가 빼 간다 = 결실. 유리판의 빛깔이 곧 그 염기(노랑 = 끼어든 C · 빨강 = 빠진 G). ⚠ 처음 바탕의 나무망치 일꾼 · 복면 도둑은 【멜빵바지 목수 · 나무망치】(인산이에스터) · 【복면 강도】(CO)와 겹쳐 구역 편집 ZB2 로 바꿨다. 원숭이는 Gemini 가 열차 쪽으로 걷게 그려 PIL 이 좌우로 뒤집는다.',
 '받침대에 가로누운 나무 사다리 밑에서 입 벌리고 자는 수리공(닫힌 연장통 · 바닥의 망치)': f'수선되지 않은 DNA 손상이 전해지면 돌연변이 전용 {C} — L10c s2. 사다리 = DNA(L38a) · 자는 수리공 = L11c 의 수리공들이 일을 안 함. ⚠ 코 방울을 그리지 않는다(【코 방울을 불며 조는 제복 징수원】 = 수동수송).',
 '해의 굵은 햇살에 녹아 처진 사다리 덩이와 해 모양 그을음 / 손뼈 비치는 회색 기계의 푸른 빛줄기에 부러진 사다리 끝': f'UV = 염기 결합 이상(이웃한 두 염기가 붙는 이량체) / X선 = DNA 절단 전용 {C} — L10c s10. 해 모양 그을음 + 녹아 붙음은 L11c 그대로 · 덩이에 든 칸과 옆 칸이 둘 다 초록 = 나란한 두 T. X선은 화면에 손뼈가 비치는 기계. ⚠ 빛줄기를 노란 번개로 그리지 않는다(【노란 번개】 = 전기적 자극) — 처음 바탕의 번개를 구역 편집 ZF2 로 푸른 쐐기 빛으로 바꿨다. ⚠ 검은 X 사진 · 꼬리 달린 연(프랭클린)과 다른 물건.',
 '사다리 위에서 갈색 약병을 기울여 보라 방울을 떨구는 작은 검은 게': f'발암물질(돌연변이원 가운데 암을 일으키는 것 — 화학 돌연변이원) 전용 {C} — L10c s11. 【작은 검은 게】 = 암 그대로 · 방울을 맞은 칸 하나가 보라 = 염기가 바뀜. 해 · 뼈 비치는 기계 · 약병 셋 = 돌연변이원.',
 '갈색 약병을 얹은 파란 물총을 겨눈 흰 가운 + 이젤의 둥근 배지 둘(흰 점 빽빽 / 셋)': f'에임스 시험(화학물질의 돌연변이 유발성 검사 — 되돌이 돌연변이 군락 수) 전용 {C} — L10c s12. 겨누다(aim) = 에임스 · 흰 점 = his⁺ 로 되돌아간 살모넬라 군락. ⚠ 【얕은 우유 접시와 Z자 쇠막대】(lacZ)와 가른다 — 이쪽은 이젤에 과녁처럼 세운 판.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('열쇠', f'★ {B} L10b s7 할아버지 신발에 끈으로 매단 금빛 열쇠 = 안티코돈 — 「세 이빨 열쇠」(L10a)가 표지다: 이빨 셋이 발밑 객차의 창 셋에 하나씩 꽂히고 셋째 이빨만 빨간 고무(요동). 매달렸어도 키나아제가 아니다 — 이빨이 셋이고 창에 꽂혔다. 꼴은 L10a 의 열쇠와 같게 PIL 이 그렸다(둥근 손잡이 고리 + 자루 + 넓적한 이빨 셋 — 막대에 가는 이빨만 있던 첫 꼴은 「빗 · 선반」으로 읽혔다). 다만 빨간 이빨은 창의 차례(셋째 창 = 코돈 셋째 자리)를 따라 손잡이 쪽이다(L10a 는 손잡이에서 먼 끝).')
add('모자', f'★ {B} L10b s1 레일 왼쪽 끝의 겨자색 중산모 = 5′ 캡(L10a 그대로). 이 그림의 사람은 맨머리(짐꾼의 작은 빨간 모자는 사람이 쓴 모자라 뜻이 없다) · 황제의 것은 월계관.')
add('구슬 — 빛깔과 놓인 곳으로 가름', f'★ {B} L10b 손끝 · 말풍선의 분홍 구슬 = 아미노산 · 체스판의 금빛 구슬 61 = 아미노산을 지정하는 코돈 · 짐꾼의 구슬 사슬 = 다 만든 폴리펩타이드(앞 끝 구슬의 빛깔 = 신호서열). {C} L10c 열차 위의 구슬 줄 = 그 mRNA 가 만드는 사슬 — 구슬 빛깔 하나 = 아미노산 하나(원본: 금 Met · 주황 Glu · 분홍 Gln · 청록 Thr · 보라 Ile / 과오: 검정 Val).')
add('지붕 위 안내인이 쥔 구슬 사슬 · 사슬 앞 끝의 빨간 구슬', f'★ [2026-11-13 17장 덧붙임] 17장 카드 F0-139 ~ 143(신호 펩타이드 약 20 aa · N 말단 · SRP = 단백질-RNA 복합체 · 막의 수용체로 · 번역 도중)을 L48d s6 에 걸었다(`apply_A17_ribo.py` — 그림 그대로 · 말만 보탬). L10b s9 이정표의 빨간 구슬 화살판 = 이 빨간 머리 구슬(소포체행 신호) · L10b s8 작은 카키 천막 지붕의 구멍으로 드는 사슬 끝의 빨간 구슬도 같다.')
add('긴 천막 막사', f'★ {B} L10b s8 · s9 왼쪽 멀리의 작은 카키 천막(지붕에 보라 짝 · 구멍으로 드는 구슬 사슬) = 소포체 — 꿰는 도중에 넣는다(번역 도중). 17장 덧붙임: F0-136 · 137 · 138(자유 · 부착 리보솜)을 L48d s3 에, F0-145(폴딩)를 s7 에 걸었다.')
